using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;

namespace EaxReverbEngine
{
    // صور مقصوصة من لقطات الواجهة الاصلية (بدون اي شعار)
    internal static class Assets
    {
        private static readonly Dictionary<string, string> Data = new Dictionary<string, string>
        {
            { "thumb_h", "" },
            { "groove_h", "iVBORw0KGgoAAAANSUhEUgAAABoAAAAECAIAAAAf9LhyAAAARUlEQVR4Xo2OMQqAQBADE0yx/v9BIn7LSwSbs3G5acMM4XGd+EebmvVLXuS4Ee4xFnNAHKuqGiHheo6E9jbn7vqEJBAAD9yMGHAA8fj3AAAAAElFTkSuQmCC" },
            { "hdr_eq", "" },
            { "hdr_mix", "" },
            { "hdr_spk", "" },
            { "ic_swirl", "" },
            { "ic_caps", "" },
            { "ic_woof", "" },
            { "ic_plus", "" },
            { "ic_grid", "" },
            { "bar_tile", "" },
            { "thumb_v", "" },
            { "spk_on", "" },
            { "spk_off", "" },
        };

        private static readonly Dictionary<string, Bitmap> Cache = new Dictionary<string, Bitmap>();

        public static Bitmap Get(string name)
        {
            lock (Cache)
            {
                Bitmap b;
                if (Cache.TryGetValue(name, out b)) return b;
                try
                {
                    string s;
                    if (Data.TryGetValue(name, out s))
                    {
                        using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(s)))
                        using (Bitmap raw = new Bitmap(ms))
                        {
                            b = new Bitmap(raw);
                        }
                    }
                }
                catch (Exception) { b = null; }
                Cache[name] = b;
                return b;
            }
        }
    }
}
